let analyticsData={officer_rankings:[],monthly_case_change:[],location_hotspots:[]};
let upcomingHearings=[];
let page = 'overview';
let activityEntries = [];
let caseStatusFilter = '';
let personStatusFilter = '';
let officerRoleFilter = '';
