function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function canManage(){return currentUser&&['Administrator','Management Head'].includes(currentUser.role)}
function initials(name=''){return String(name||'').split(/\s+/).filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function parseJsonValue(value){if(typeof value!=='string')return value;try{return JSON.parse(value)}catch{return value}}
function statusClass(s){return s==='Active'?'active':s==='Closed'?'closed':s==='Under review'?'review':''}
function dateShort(d){if(!d)return '—';let dt=new Date(d+'T00:00:00');return dt.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})}
function trashIcon(){return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M10 11v6m4-6v6M5 7l1 14h12l1-14M9 7V4h6v3"/></svg>'}
function caseRow(c,compact=false){if(compact)return `<tr data-case-row="${esc(c.id)}"><td><span class="case-id">${esc(c.id)}</span></td><td><button type="button" class="case-title case-detail-link" data-view-case="${esc(c.id)}" title="View case and history">${esc(c.title)}</button><div class="case-sub" title="${esc(c.category)} · ${esc(c.location||'Location not set')}">${esc(c.category)} · ${esc(c.location||'Location not set')}</div></td><td><span class="pill ${statusClass(c.status)}">${esc(c.status)}</span></td><td>${dateShort(c.date)}</td></tr>`;return `<tr data-case-row="${esc(c.id)}"><td><span class="case-id">${esc(c.id)}</span></td><td><button type="button" class="case-title case-detail-link" data-view-case="${esc(c.id)}" title="View case and history">${esc(c.title)}</button><div class="case-sub" title="${esc(c.category)} · ${esc(c.location||'Location not set')}">${esc(c.category)} · ${esc(c.location||'Location not set')}</div></td><td><span class="pill ${statusClass(c.status)}">${esc(c.status)}</span></td><td><div class="officer"><span class="mini-avatar">${esc(initials(c.officer))}</span>${esc(c.officer||'Unassigned')}</div></td><td>${dateShort(c.date)}</td><td class="row-actions"><span class="row-action-group"><button type="button" class="row-action" data-view-case="${esc(c.id)}" aria-label="View history for ${esc(c.id)}" title="View case history">◷</button>${canManage()?`<button type="button" class="row-action" data-edit="${esc(c.id)}" aria-label="Edit ${esc(c.id)}" title="Edit">✎</button><button type="button" class="row-action danger" data-delete-case="${esc(c.id)}" aria-label="Delete ${esc(c.id)}" title="Delete">${trashIcon()}</button>`:''}</span></td></tr>`}
function table(rows){return `<div class="table-panel panel"><table class="case-table case-record-table"><thead><tr><th>CASE ID</th><th>CASE TITLE</th><th>STATUS</th><th>ASSIGNED TO</th><th>DATE OPENED</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="6" class="empty-state">No records match your search. Try another search or status filter.</td></tr>'}</tbody></table></div>`}
function timeAgo(value){const minutes=Math.max(0,Math.floor((Date.now()-new Date(value).getTime())/60000));if(minutes<1)return 'Just now';if(minutes<60)return `${minutes} min ago`;if(minutes<1440)return `${Math.floor(minutes/60)} hr ago`;return `${Math.floor(minutes/1440)} days ago`}
function activity(limit=4){const items=activityEntries.slice(0,limit);return `<div class="activity-list">${items.map((item,i)=>`<div class="activity-item"><span class="activity-dot ${i===1?'amber':i===2?'blue':''}">${i===0?'＋':i===1?'↻':i===2?'♙':'✓'}</span><div class="activity-copy"><strong>${esc(item.title)}</strong><small>${esc(item.detail)} · ${timeAgo(item.time)}</small></div></div>`).join('')}</div>`}
function heading(kicker,title,desc,action=''){return `<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function newButton(label='New case record'){return canManage()?`<button class="btn primary" data-new>＋ <span>${label}</span></button>`:''}

async function apiRequest(path,{method='GET',body}={}){let response;try{response=await fetch(path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined})}catch(error){throw new Error(`Cannot reach the CASEWORK API at ${location.origin}. Open the app at the same address printed by “python -u backend/api.py” (for example, http://127.0.0.1:8010), then check ${location.origin}/api/health.`)}const type=response.headers.get('content-type')||'',isLogin=path==='/api/auth/login';if(!response.ok){let message='Request failed. Please try again.',code='';if(type.includes('application/json')){const data=await response.json();message=data.error||message;code=data.code||''}else if(isLogin){message=response.status===405?'Sign-in is unavailable here because this host is not running the CASEWORK API.':'Unable to sign in. Please try again.'}else message=await response.text()||message;if(isLogin&&response.status===401)message='Incorrect username or password.';const error=new Error(message);error.status=response.status;error.code=code;if(code==='session_expired'){currentUser=null;const screen=document.querySelector('#loginScreen'),loginError=document.querySelector('#loginError');if(screen)screen.hidden=false;if(loginError){loginError.textContent=message;loginError.hidden=false}}throw error}return type.includes('application/json')?response.json():response}
async function downloadCsv(path){try{const response=await apiRequest(path);const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(response.headers.get('content-disposition')||'').match(/filename="?([^";]+)"?/i)?.[1]||'casework-report.csv';document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Report downloaded.')}catch(error){toast(error.message)}}
let renderRequest=0;async function render({refreshData=true}={}){const requestId=++renderRequest;document.querySelector('#loginScreen').hidden=!!currentUser;if(!currentUser){app.removeAttribute('aria-busy');renderContent();return}app.removeAttribute('aria-busy');renderContent();if(!refreshData)return;try{const cid=false;const [dash,casesData,peopleData,officersData,activityData,reports,analytics]=await Promise.all([apiRequest('/api/dashboard'),apiRequest('/api/cases?limit=250'),cid?Promise.resolve({items:[]}):apiRequest('/api/persons'),cid?Promise.resolve({items:[]}):apiRequest('/api/officers'),cid?Promise.resolve({items:[]}):apiRequest('/api/activity'),cid?Promise.resolve({}):apiRequest('/api/reports'),cid?Promise.resolve({officer_rankings:[],monthly_case_change:[],location_hotspots:[]}):apiRequest('/api/analytics')]);if(requestId!==renderRequest||!currentUser)return;dashboardStats=dash.counts;dashboardRecent=dash.recent;upcomingHearings=dash.upcoming_hearings||[];records=casesData.items;persons=peopleData.items;officers=officersData.items;activityEntries=activityData.items;reportData=reports;analyticsData=analytics;if(currentUser.role==='Management Head'&&page==='users'){userAccounts=(await apiRequest('/api/users')).items}else if(currentUser.role!=='Management Head')userAccounts=[];workspaceLoadError='';renderContent()}catch(error){if(requestId!==renderRequest||!currentUser)return;workspaceLoadError=error.message||'The CASEWORK API could not load workspace data.';renderContent();toast(`Workspace data could not load: ${workspaceLoadError}`)}}
function analyticsTable(rows,columns){return `<div class="table-panel analytics-table-wrap"><table class="case-table"><thead><tr>${columns.map(([,label])=>`<th>${esc(label)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${columns.map(([key])=>`<td>${esc(row[key]??'—')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${columns.length}" class="empty-state">No matching data yet.</td></tr>`}</tbody></table></div>`}
function analyticsChart(rows,labelKey,valueKey){const top=Math.max(1,...rows.map(row=>Number(row[valueKey])||0));return `<div class="analytics-bars">${rows.length?rows.map(row=>`<div class="analytics-bar-row"><span title="${esc(row[labelKey])}">${esc(row[labelKey])}</span><i><b style="width:${Math.max(3,(Number(row[valueKey])||0)/top*100)}%"></b></i><strong>${esc(row[valueKey]??0)}</strong></div>`).join(''):'<p class="case-sub">No chart data yet.</p>'}</div>`}
function upcomingHearingsCard(){const list=upcomingHearings.slice(0,5);return `<section class="panel upcoming-hearings"><div class="panel-head"><div><h2>Upcoming hearings</h2><p>Scheduled in the next 14 days</p></div><span class="hearing-count">${upcomingHearings.length}</span></div>${list.length?`<div class="upcoming-hearing-list">${list.map(item=>`<button type="button" class="upcoming-hearing-row" data-hearing-case="${esc(item.case_reference)}"><span class="hearing-date">${esc(new Date(`${item.hearing_date}T00:00:00`).toLocaleDateString('en-US',{month:'short',day:'numeric'}))}</span><span class="upcoming-hearing-copy"><strong>${esc(item.case_reference)} · ${esc(item.court)}</strong><small>${esc(item.case_title)} · ${esc(item.status)}</small></span><span class="hearing-arrow">→</span></button>`).join('')}</div>`:'<p class="upcoming-hearing-empty">No hearings scheduled for the next 14 days.</p>'}</section>`}
function renderContent(){document.querySelector('#loginScreen').hidden=!!currentUser;if(!currentUser)return;if(page==='users'&&currentUser.role!=='Management Head')page='overview';updateAccountUI();document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelector('#breadcrumb').textContent=({overview:'Overview',cases:'Case records',people:'Persons of interest',officers:'Team directory',reports:'Reports',analytics:'Analytics',activity:'Activity log',users:'User management'})[page];document.querySelector('#caseNavCount').textContent=String(dashboardStats.total||records.length).padStart(2,'0');
 if(page==='overview'){const today=new Date();const activeCount=dashboardStats.active||0;const reviewCount=dashboardStats.review||0;const closedCount=dashboardStats.closed||0;app.innerHTML=`${heading(today.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase(),`Good morning, ${esc(currentUser.name.split(' ')[0])} <span style="color:#b77d30">✦</span>`,'Here’s what’s happening across your district today.',newButton())}<div class="stats"><div class="stat-card"><div class="stat-top">Total case records <span class="stat-icon">▤</span></div><div class="stat-value">${dashboardStats.total||0}</div><div class="stat-note">Records in this workspace</div></div><div class="stat-card"><div class="stat-top">Active investigations <span class="stat-icon amber">◷</span></div><div class="stat-value">${activeCount}</div><div class="stat-note">Currently marked active</div></div><div class="stat-card"><div class="stat-top">Cases under review <span class="stat-icon blue">⌕</span></div><div class="stat-value">${reviewCount}</div><div class="stat-note">Awaiting review</div></div><div class="stat-card"><div class="stat-top">Closed cases <span class="stat-icon purple">✓</span></div><div class="stat-value">${closedCount}</div><div class="stat-note">Marked closed</div></div></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Recent case records</h2><p>Latest updates from your district</p></div><button class="text-link" data-go="cases">View all cases →</button></div><table class="case-table overview-case-table"><thead><tr><th>CASE ID</th><th>CASE TITLE</th><th>STATUS</th><th>DATE</th></tr></thead><tbody>${dashboardRecent.map(c=>caseRow(c,true)).join('')||'<tr><td colspan="4" class="empty-state">No case records yet. Create a record to get started.</td></tr>'}</tbody></table></section><div class="side-panels">${upcomingHearingsCard()}<section class="panel"><div class="panel-head"><div><h2>Recent activity</h2><p>Updates from your team</p></div><button class="text-link" data-go="activity">See all</button></div>${activity()}</section><section class="panel"><div class="panel-head"><div><h2>Quick actions</h2><p>Common tasks, one click away</p></div></div><div class="quick-actions">${canManage()?'<button class="quick-action" data-add-evidence><span>＋</span> Record evidence</button>':''}${currentUser.role!=='Operator'?'<button class="quick-action" data-go="people"><span>♙</span> Find a person</button><button class="quick-action" data-go="reports"><span>▥</span> View reports</button><button class="quick-action" data-go="officers"><span>♧</span> Team directory</button>':''}</div></section></div></div>`}
 else if(page==='cases'){app.innerHTML=`${heading('RECORDS','Case records','Search, review and manage case records across your district.',newButton())}<div class="toolbar"><label class="search-wrap"><span>⌕</span><input id="caseSearch" placeholder="Search by case ID, title, officer or location…"></label><select class="btn secondary filter-select" id="filterButton" aria-label="Filter cases by status"><option value="">All statuses</option><option>Active</option><option>Under review</option><option>Pending</option><option>Closed</option></select><button class="btn secondary" id="exportButton">⇩ &nbsp; Export</button></div><div id="caseTable">${table(records.map(c=>caseRow(c)).join(''))}</div>`}
 else if(page==='people'){app.innerHTML=`${heading('RECORDS','Persons of interest','View and manage person records linked to active cases.',canManage()?`<button class="btn primary" data-new-person>＋ Add person</button>`:'')}<div class="toolbar"><label class="search-wrap"><span>⌕</span><input id="peopleSearch" placeholder="Search by name, case or charge…"></label><select class="btn secondary filter-select" id="personFilter" aria-label="Filter persons by status"><option value="">All statuses</option>${['Under investigation','In custody','Released on bail','Wanted','Unknown'].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="person-grid" id="peopleGrid">${persons.map(personCard).join('')||'<div class="empty-state">No person records yet.</div>'}</div>`}
 else if(page==='officers'){app.innerHTML=`${heading('PEOPLE','Team directory','District personnel and current case assignments.',canManage()?`<button class="btn primary" data-new-officer>＋ Add team member</button>`:'')}<div class="toolbar"><label class="search-wrap"><span>⌕</span><input id="officerSearch" placeholder="Search team members…"></label><select class="btn secondary filter-select" id="roleFilter" aria-label="Filter officers by role"><option value="">All roles</option>${[...new Set(officers.map(o=>o.role))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="officer-grid" id="officerGrid">${officers.map(officerCard).join('')||'<div class="empty-state">No team members yet.</div>'}</div>`}
 else if(page==='reports'){app.innerHTML=`${heading('INSIGHTS','Reports & analytics','Download current summaries calculated from your workspace records.')}<div class="report-grid">${[['▤','Case overview','Current case totals by status.'],['◷','Investigation activity','Saved case creation and update actions.'],['♙','Team workload','Case assignments grouped by officer.'],['⌖','Incident locations','Case distribution by recorded location.'],['✓','Resolution summary','Closed cases and current case status totals.'],['⇩','Export records','Download all current case record fields.'],['◷','Days open','Current case age calculated from its opening date.']].map((r,i)=>`<article class="report-card"><span class="report-icon">${r[0]}</span><h3>${r[1]}</h3><p>${r[2]}</p><button class="text-link" data-report="${i}">Download CSV →</button></article>`).join('')}</div>`}
 else if(page==='analytics'){const a=analyticsData;app.innerHTML=`${heading('INSIGHTS','Analytics','Officer performance, monthly case trends, and location hotspots from your database.')}<div class="analytics-grid"><section class="panel analytics-panel"><div class="panel-head"><div><h2>Closed cases by officer</h2><p>Ranked with SQL RANK() across ties</p></div><button class="btn secondary" data-analytics-export="officers">Export CSV</button></div>${analyticsChart(a.officer_rankings,'officer_name','closed_cases')}${analyticsTable(a.officer_rankings,[['rank','RANK'],['officer_name','OFFICER'],['closed_cases','CASES CLOSED'],['total_cases','TOTAL CASES']])}</section><section class="panel analytics-panel"><div class="panel-head"><div><h2>Monthly case change</h2><p>Month totals compared with the previous month using LAG()</p></div><button class="btn secondary" data-analytics-export="monthly">Export CSV</button></div>${analyticsChart(a.monthly_case_change,'month','case_count')}${analyticsTable(a.monthly_case_change,[['month','MONTH'],['case_count','CASES'],['previous_month_cases','PREVIOUS MONTH'],['case_change','CHANGE']])}</section><section class="panel analytics-panel"><div class="panel-head"><div><h2>Location hotspots</h2><p>Locations with at least two recorded cases</p></div><button class="btn secondary" data-analytics-export="hotspots">Export CSV</button></div>${analyticsChart(a.location_hotspots,'location','case_count')}${analyticsTable(a.location_hotspots,[['location','LOCATION'],['case_count','CASES']])}</section></div>`}
 else if(page==='users'){app.innerHTML=`${heading('ADMINISTRATION','User management','Create accounts, assign access roles, or disable access.')}<div class="user-management-grid"><section class="panel user-create-panel"><h2>Create account</h2><form id="createUserForm" class="form-grid"><label>Full name<input name="name" maxlength=160 required></label><label>Username<input name="username" maxlength=80 required></label><label>Temporary password<input name="password" type="password" minlength=12 autocomplete="new-password" required></label><label>Role<select name="role" id="newUserRole"><option>Management Head</option><option>Administrator</option><option>Operator</option></select></label><button class="btn primary" type="submit">Create account</button></form></section><section class="panel table-panel user-table-wrap"><table class="case-table user-table"><thead><tr><th>NAME</th><th>USERNAME</th><th>ROLE</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${userAccounts.map(account=>`<tr><td>${esc(account.name)}</td><td>${esc(account.username)}</td><td><select aria-label="Role for ${esc(account.username)}" data-user-role="${account.id}" ${account.username===currentUser.username?'disabled title="You cannot change your own Management Head role"':''}>${['Management Head','Administrator','Operator'].map(role=>`<option ${role===account.role?'selected':''}>${role}</option>`).join('')}</select></td><td><span class="user-state ${account.active?'active':'disabled'}">${account.active?'Active':'Disabled'}</span></td><td><div class="user-row-actions"><button class="btn secondary" data-save-user-role="${account.id}" ${account.username===currentUser.username?'disabled title="You cannot change your own Management Head role"':''}>Save role</button><button class="btn secondary danger-text" data-toggle-user="${account.id}" data-active="${account.active?'1':'0'}" ${account.username===currentUser.username?'disabled title="You cannot disable your own Management Head account"':''}>${account.active?'Disable':'Enable'}</button><button class="btn secondary danger-text" data-delete-user="${account.id}" ${account.username===currentUser.username?'disabled title="You cannot delete your own account"':''}>Delete</button></div></td></tr>`).join('')||'<tr><td colspan="6" class="empty-state">No user accounts.</td></tr>'}</tbody></table></section></div>`}
 else{app.innerHTML=`${heading('WORKSPACE','Activity log','A timeline of updates and actions in your district.')}<section class="panel activity-full"><div class="panel-head"><div><h2>Recent activity</h2><p>Latest team updates</p></div><span class="case-sub">${activityEntries.length} saved actions</span></div>${activity(30)}</section>`}
 if(workspaceLoadError){app.insertAdjacentHTML('afterbegin',`<div class="workspace-load-error" role="alert"><strong>Could not load live records.</strong> ${esc(workspaceLoadError)} <button type="button" id="retryWorkspaceLoad">Retry</button></div>`);document.querySelector('#retryWorkspaceLoad').onclick=()=>{workspaceLoadError='';void render()}}bindPageEvents();}
function personCard(p){const links=p.cases|| (p.case?[{case_reference:p.case,role:'person_of_interest'}]:[]);const related=links.map(x=>`${x.case_reference} (${x.role})`).join(', ');return `<article class="person-card" data-person-search="${esc((p.name+related+p.charge).toLowerCase())}" data-person-status="${esc(p.status)}"><div class="person-head"><span class="person-avatar">${esc(initials(p.name))}</span><div><h3>${esc(p.name)}</h3><small>${esc(links.length?`${links.length} linked case${links.length===1?'':'s'}`:'No linked case')}</small></div></div><div class="person-meta"><div><small>PRIMARY CHARGE</small><strong>${esc(p.charge)}</strong></div><div><small>STATUS</small><span class="pill ${p.status==='In custody'?'active':'review'}">${esc(p.status)}</span></div><div><small>AGE</small><strong>${esc(p.age??'—')}</strong></div><div class="person-linked-cases"><small>LINKED CASES · ROLE</small>${links.length?links.map(link=>`<div class="person-case-link"><button class="text-link view-case" data-person-case="${esc(link.case_reference)}">${esc(link.case_reference)} →</button><span>${esc(link.role.replaceAll('_',' '))}</span></div>`).join(''):'<strong>—</strong>'}</div></div><div class="person-footer">${canManage()?`<div class="person-actions"><button class="btn secondary" data-edit-person="${esc(p.id)}">Edit</button><button class="btn delete-btn" data-delete-person="${esc(p.id)}">${trashIcon()}<span>Delete</span></button></div>`:''}</div></article>`}
function officerCard(o){return `<article class="officer-card" data-officer="${esc(o.name.toLowerCase())}" data-role="${esc(o.role)}"><div class="officer-photo">${esc(initials(o.name))}</div><h3>${esc(o.name)}</h3><small>${esc(o.role)}</small><div class="officer-meta"><div><small>BADGE ID</small><strong>${esc(o.badge)}</strong></div><div><small>OPEN CASES</small><strong>${o.cases||0}</strong></div></div>${canManage()?`<div class="officer-actions"><button class="btn secondary" data-edit-officer="${esc(o.id)}">Edit</button><button class="btn secondary danger-text" data-delete-officer="${esc(o.id)}">Delete</button></div>`:''}</article>`}
function bindCaseActions(){document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openDialog(records.find(c=>c.id===b.dataset.edit)));document.querySelectorAll('[data-delete-case]').forEach(b=>b.onclick=()=>deleteCase(b.dataset.deleteCase))}
async function showCaseById(id){await navigate('cases');const search=document.querySelector('#caseSearch');search.value=id;await filterCases();const row=[...document.querySelectorAll('[data-case-row]')].find(item=>item.dataset.caseRow===id);if(row){row.scrollIntoView({behavior:'smooth',block:'center'});row.classList.add('row-highlight');setTimeout(()=>row.classList.remove('row-highlight'),1800)}}
function bindPageEvents(){document.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>openDialog());document.querySelectorAll('[data-add-evidence]').forEach(b=>b.onclick=openEvidenceCasePicker);document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));bindCaseActions();document.querySelectorAll('[data-view-case]').forEach(b=>b.onclick=()=>openCaseDetail(b.dataset.viewCase));document.querySelectorAll('[data-hearing-case]').forEach(b=>b.onclick=()=>openCaseDetail(b.dataset.hearingCase));document.querySelectorAll('[data-new-person]').forEach(b=>b.onclick=()=>openEntityDialog('person'));document.querySelectorAll('[data-edit-person]').forEach(b=>b.onclick=()=>openEntityDialog('person',persons.find(p=>String(p.id)===b.dataset.editPerson)));document.querySelectorAll('[data-delete-person]').forEach(b=>b.onclick=()=>deleteEntity('person',b.dataset.deletePerson));document.querySelectorAll('[data-new-officer]').forEach(b=>b.onclick=()=>openEntityDialog('officer'));document.querySelectorAll('[data-edit-officer]').forEach(b=>b.onclick=()=>openEntityDialog('officer',officers.find(o=>String(o.id)===b.dataset.editOfficer)));document.querySelectorAll('[data-delete-officer]').forEach(b=>b.onclick=()=>deleteEntity('officer',b.dataset.deleteOfficer));document.querySelectorAll('[data-toast]').forEach(b=>b.onclick=()=>toast(b.dataset.toast));document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>downloadReport(Number(b.dataset.report)));document.querySelectorAll('[data-analytics-export]').forEach(b=>b.onclick=()=>downloadCsv(`/api/reports/export?type=analytics-${b.dataset.analyticsExport}`));document.querySelectorAll('[data-person-case]').forEach(b=>b.onclick=()=>showCaseById(b.dataset.personCase));
 const search=document.querySelector('#caseSearch');if(search)search.oninput=filterCases;const f=document.querySelector('#filterButton');if(f)f.onchange=filterCases;const psearch=document.querySelector('#peopleSearch');if(psearch)psearch.oninput=filterPeople;const pf=document.querySelector('#personFilter');if(pf)pf.onchange=filterPeople;const osearch=document.querySelector('#officerSearch');if(osearch)osearch.oninput=filterOfficers;const rf=document.querySelector('#roleFilter');if(rf)rf.onchange=filterOfficers;const ex=document.querySelector('#exportButton');if(ex)ex.onclick=exportCsv;}
async function filterCases(){try{const params=new URLSearchParams({q:document.querySelector('#caseSearch').value,status:document.querySelector('#filterButton').value});const data=await apiRequest(`/api/cases?${params}`);records=data.items;document.querySelector('#caseTable').innerHTML=table(records.map(c=>caseRow(c)).join(''));bindCaseActions()}catch(error){toast(error.message)}}
async function filterPeople(){try{const params=new URLSearchParams({q:document.querySelector('#peopleSearch').value,status:document.querySelector('#personFilter').value});persons=(await apiRequest(`/api/persons?${params}`)).items;const grid=document.querySelector('#peopleGrid');grid.innerHTML=persons.map(personCard).join('')||'<div class="empty-state">No person records yet.</div>';bindPageEvents()}catch(error){toast(error.message)}}
async function filterOfficers(){try{const params=new URLSearchParams({q:document.querySelector('#officerSearch').value,role:document.querySelector('#roleFilter').value});officers=(await apiRequest(`/api/officers?${params}`)).items;const grid=document.querySelector('#officerGrid');grid.innerHTML=officers.map(officerCard).join('')||'<div class="empty-state">No team members yet.</div>';bindPageEvents()}catch(error){toast(error.message)}}
function evidenceEditorMarkup(item=null){const editing=!!item;const collectorOptions=officers.map(o=>`<option value="${esc(o.id)}" ${String(o.id)===String(item?.collected_by)?'selected':''}>${esc(o.name)} · ${esc(o.badge)}</option>`).join('');return `<form id="evidenceForm" class="evidence-editor" ${editing?`data-edit-id="${esc(item.id)}"`:''}><div class="evidence-editor-heading"><strong>${editing?'Edit evidence details':'Add evidence'}</strong>${editing?'<button type="button" class="text-link" data-cancel-evidence>Edit cancelled</button>':''}</div><div class="evidence-form-grid"><label>Description<input name="description" maxlength="4000" required value="${esc(item?.description||'')}"></label><label>Evidence type<input name="type" maxlength="80" required value="${esc(item?.type||'')}"></label><label>SHA-256 fingerprint<input name="hash" maxlength="64" required pattern="[a-fA-F0-9]{64}" title="Enter a 64-character SHA-256 hexadecimal fingerprint" value="${esc(item?.hash||'')}" ${editing?'readonly':''}></label><label>Storage path<input name="storage_path" maxlength="500" required value="${esc(item?.storage_path||'')}"></label>${editing?'':`<label>Collected by<select name="collected_by" required><option value="">Choose an officer</option>${collectorOptions}</select></label>`}</div><p class="evidence-note">Store the file in your approved evidence storage. CASEWORK records its path and fingerprint; it does not upload files.</p><div class="dialog-actions"><button type="submit" class="btn primary">${editing?'Save details':'Record evidence'}</button></div></form>`}
function evidenceCard(item){const timeline=item.custody_timeline||[];return `<article class="evidence-card"><div class="evidence-card-heading"><div><span class="eyebrow">${esc(item.type)}</span><h4>${esc(item.description)}</h4></div>${canManage()?`<div class="evidence-actions"><button type="button" class="btn secondary" data-evidence-edit="${esc(item.id)}">Edit</button><button type="button" class="btn delete-btn" data-evidence-delete="${esc(item.id)}">Delete</button></div>`:''}</div><dl class="evidence-metadata"><div><dt>SHA-256</dt><dd><code>${esc(item.hash)}</code></dd></div><div><dt>Storage path</dt><dd>${esc(item.storage_path)}</dd></div><div><dt>Collected by</dt><dd>${esc(item.collected_by_name)} · ${esc(new Date(item.collected_at).toLocaleString())}</dd></div><div><dt>Current custodian</dt><dd>${esc(timeline.at(-1)?.to_officer_name||item.collected_by_name)}</dd></div></dl><section class="custody-timeline"><h5>Chain of custody</h5>${timeline.map(entry=>`<article class="custody-event"><span class="history-marker"></span><div><strong>${entry.event==='collected'?'Collected':`Transferred: ${esc(entry.from_officer_name||'Unknown')} → ${esc(entry.to_officer_name)}`}</strong><p>${esc(entry.purpose)}</p><small>${esc(new Date(entry.transferred_at).toLocaleString())}</small></div></article>`).join('')}</section>${canManage()?`<form class="evidence-transfer-form" data-evidence-transfer="${esc(item.id)}"><label>Transfer to<select name="to_officer" required><option value="">Choose receiving officer</option>${officers.map(o=>`<option value="${esc(o.id)}">${esc(o.name)} · ${esc(o.badge)}</option>`).join('')}</select></label><label>Purpose<input name="purpose" maxlength="500" required placeholder="e.g. Laboratory analysis"></label><button class="btn secondary" type="submit">Transfer custody</button></form>`:''}</article>`}
function hearingEditorMarkup(item=null){const editing=!!item;return `<form id="hearingForm" class="hearing-editor" ${editing?`data-edit-id="${esc(item.id)}"`:''}><div class="hearing-editor-heading"><strong>${editing?'Edit court hearing':'Schedule a hearing'}</strong>${editing?'<button type="button" class="text-link" data-cancel-hearing>Cancel</button>':''}</div><div class="hearing-form-grid"><label>Court<input name="court" maxlength="240" required value="${esc(item?.court||'')}"></label><label>Hearing date<input name="hearing_date" type="date" required value="${esc(item?.hearing_date||'')}"></label><label>Status<select name="status">${['Scheduled','Adjourned','Completed','Cancelled'].map(status=>`<option ${status===(item?.status||'Scheduled')?'selected':''}>${status}</option>`).join('')}</select></label><label>Outcome<input name="outcome" maxlength="4000" value="${esc(item?.outcome||'')}"></label><label class="hearing-notes-field">Notes<textarea name="notes" maxlength="8000" rows="3">${esc(item?.notes||'')}</textarea></label></div><div class="dialog-actions"><button type="submit" class="btn primary">${editing?'Save hearing':'Schedule hearing'}</button></div></form>`}
function hearingCard(item){return `<article class="hearing-card"><div class="hearing-card-main"><div><span class="pill ${item.status==='Scheduled'?'active':item.status==='Completed'?'closed':'review'}">${esc(item.status)}</span><h4>${esc(item.court)}</h4><p>${esc(new Date(`${item.hearing_date}T00:00:00`).toLocaleDateString('en-US',{weekday:'short',month:'long',day:'numeric',year:'numeric'}))}</p></div>${canManage()?`<div class="hearing-actions"><button type="button" class="btn secondary" data-hearing-edit="${esc(item.id)}">Edit</button><button type="button" class="btn delete-btn" data-hearing-delete="${esc(item.id)}">Delete</button></div>`:''}</div>${item.outcome?`<p class="hearing-outcome"><strong>Outcome:</strong> ${esc(item.outcome)}</p>`:''}${item.notes?`<p class="hearing-notes">${esc(item.notes)}</p>`:''}</article>`}
async function openCaseDetail(id){
 const record=records.find(item=>item.id===id)||dashboardRecent.find(item=>item.id===id);if(!record)return;const dialog=document.querySelector('#caseDetailDialog'),body=document.querySelector('#caseDetailBody');document.querySelector('#caseDetailTitle').textContent=record.id;body.innerHTML='<div class="empty-state">Loading case history and evidence…</div>';dialog.showModal();
 try{const [detail,history,evidence,hearingData]=await Promise.all([apiRequest(`/api/cases/${encodeURIComponent(id)}`),apiRequest(`/api/cases/${encodeURIComponent(id)}/history`),apiRequest(`/api/cases/${encodeURIComponent(id)}/evidence`),apiRequest(`/api/cases/${encodeURIComponent(id)}/hearings`)]),item=detail.item||record;const timeline=history.items.map(entry=>{const action=String(entry.action||'updated').toLowerCase();const title=entry.type==='status'?`Status changed: ${entry.old_status} → ${entry.new_status}`:action==='insert'||action==='created'?'Case created':`Case ${action}`;return `<article class="history-item"><span class="history-marker"></span><div class="history-content"><strong>${esc(title)}</strong><small>${esc(entry.changed_by||'System')} · ${esc(new Date(entry.changed_at).toLocaleString())}</small>${entry.type==='record'?`<details><summary>Record values</summary><pre>${esc(JSON.stringify({before:parseJsonValue(entry.old_values),after:parseJsonValue(entry.new_values)},null,2))}</pre></details>`:''}</div></article>`}).join('');const resolution=item.resolution?`<div class="case-resolution"><strong>Resolution</strong><p>${esc(item.resolution)}</p></div>`:'';const closeForm=canManage()&&item.status!=='Closed'?`<form id="closeCaseForm" class="close-case-form"><label for="closeResolution">Resolution</label><textarea id="closeResolution" name="resolution" maxlength="2000" required placeholder="Record the outcome before closing this case"></textarea><button class="btn primary" type="submit">Close case</button></form>`:'';const evidenceItems=evidence.items||[],hearingItems=hearingData.items||[];body.innerHTML=`<div class="case-detail-summary"><span class="pill ${statusClass(item.status)}">${esc(item.status)}</span><h3>${esc(item.title)}</h3><p>${esc(item.category)} · ${esc(item.officer||'Unassigned')} · ${esc(item.location||'Location not set')}</p></div><div class="case-detail-tabs" role="tablist"><button type="button" class="case-detail-tab active" role="tab" aria-selected="true" data-case-tab="overview">Overview</button><button type="button" class="case-detail-tab" role="tab" aria-selected="false" data-case-tab="evidence">Evidence & custody <span>${evidenceItems.length}</span></button><button type="button" class="case-detail-tab" role="tab" aria-selected="false" data-case-tab="hearings">Hearings <span>${hearingItems.length}</span></button></div><section data-case-panel="overview"><div class="case-resolution-wrap">${resolution}</div>${canManage()?`<form id="assignCaseForm" class="assign-case-form"><label>Assign to team member<select name="officer_id" required><option value="">Choose a team member</option>${officers.map(officer=>`<option value="${esc(officer.id)}" ${String(officer.id)===String(item.officer_id)?'selected':''}>${esc(officer.name)} · ${esc(officer.role)}</option>`).join('')}</select></label><button class="btn secondary" type="submit">Assign case</button></form>`:''}${closeForm}<section class="case-history"><h3>Case history</h3>${timeline?`<div class="history-timeline">${timeline}</div>`:'<p class="case-sub">No history recorded for this case.</p>'}</section></section><section data-case-panel="evidence" hidden>${canManage()?evidenceEditorMarkup():''}<div class="evidence-list">${evidenceItems.map(evidenceCard).join('')||'<p class="empty-state">No evidence has been recorded for this case.</p>'}</div></section><section data-case-panel="hearings" hidden>${canManage()?hearingEditorMarkup():''}<div class="hearing-list">${hearingItems.map(hearingCard).join('')||'<p class="empty-state">No court hearings recorded for this case.</p>'}</div></section>`;
 body.querySelectorAll('[data-case-tab]').forEach(tab=>tab.onclick=()=>{body.querySelectorAll('[data-case-tab]').forEach(button=>{const active=button===tab;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))});body.querySelectorAll('[data-case-panel]').forEach(panel=>panel.hidden=panel.dataset.casePanel!==tab.dataset.caseTab)});
 const assignForm=body.querySelector('#assignCaseForm');if(assignForm)assignForm.addEventListener('submit',async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(assignForm).entries());try{await apiRequest(`/api/cases/${encodeURIComponent(id)}/assign`,{method:'POST',body:data});dialog.close();await openCaseDetail(id);toast('Case assigned to '+officers.find(officer=>String(officer.id)===String(data.officer_id))?.name+'.')}catch(error){toast(error.message)}});
 const closeFormNode=body.querySelector('#closeCaseForm');if(closeFormNode)closeFormNode.addEventListener('submit',async event=>{event.preventDefault();const button=closeFormNode.querySelector('[type=submit]');button.disabled=true;try{await apiRequest(`/api/cases/${encodeURIComponent(id)}/close`,{method:'POST',body:{resolution:closeFormNode.elements.resolution.value}});dialog.close();await render();await openCaseDetail(id);toast('Case closed and resolution saved.')}catch(error){toast(error.message);button.disabled=false}});
 const evidenceForm=body.querySelector('#evidenceForm');if(evidenceForm)evidenceForm.addEventListener('submit',async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(evidenceForm).entries()),editId=evidenceForm.dataset.editId;try{await apiRequest(editId?`/api/evidence/${encodeURIComponent(editId)}`:`/api/cases/${encodeURIComponent(id)}/evidence`,{method:editId?'PUT':'POST',body:data});dialog.close();await openCaseDetail(id);document.querySelector('[data-case-tab="evidence"]')?.click();toast(editId?'Evidence details updated.':'Evidence recorded.')}catch(error){toast(error.message)}});
 body.querySelectorAll('[data-evidence-edit]').forEach(button=>button.onclick=()=>{const entry=evidenceItems.find(e=>String(e.id)===button.dataset.evidenceEdit);if(!entry)return;body.querySelector('#evidenceForm')?.replaceWith(document.createRange().createContextualFragment(evidenceEditorMarkup(entry)));bindEvidenceForm(body,id,dialog)});
 body.querySelectorAll('[data-evidence-delete]').forEach(button=>button.onclick=async()=>{if(!confirm('Delete this evidence record? Evidence with transfer history cannot be deleted.'))return;try{await apiRequest(`/api/evidence/${encodeURIComponent(button.dataset.evidenceDelete)}`,{method:'DELETE'});dialog.close();await openCaseDetail(id);document.querySelector('[data-case-tab="evidence"]')?.click();toast('Evidence record deleted.')}catch(error){toast(error.message)}});
 body.querySelectorAll('[data-evidence-transfer]').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form).entries());try{await apiRequest(`/api/evidence/${encodeURIComponent(form.dataset.evidenceTransfer)}/transfer`,{method:'POST',body:data});dialog.close();await openCaseDetail(id);document.querySelector('[data-case-tab="evidence"]')?.click();toast('Custody transfer recorded.')}catch(error){toast(error.message)}}));
 const cancelEdit=body.querySelector('[data-cancel-evidence]');if(cancelEdit)cancelEdit.onclick=()=>{body.querySelector('#evidenceForm')?.replaceWith(document.createRange().createContextualFragment(evidenceEditorMarkup()));bindEvidenceForm(body,id,dialog)};
 const hearingForm=body.querySelector('#hearingForm');if(hearingForm)bindHearingForm(body,id,dialog);body.querySelectorAll('[data-hearing-edit]').forEach(button=>button.onclick=()=>{const entry=hearingItems.find(h=>String(h.id)===button.dataset.hearingEdit);if(!entry)return;body.querySelector('#hearingForm')?.replaceWith(document.createRange().createContextualFragment(hearingEditorMarkup(entry)));bindHearingForm(body,id,dialog)});body.querySelectorAll('[data-hearing-delete]').forEach(button=>button.onclick=async()=>{if(!confirm('Delete this hearing record?'))return;try{await apiRequest(`/api/hearings/${encodeURIComponent(button.dataset.hearingDelete)}`,{method:'DELETE'});dialog.close();await openCaseDetail(id);document.querySelector('[data-case-tab=hearings]')?.click();toast('Hearing deleted.')}catch(error){toast(error.message)}});
 }catch(error){body.innerHTML=`<p class="login-error">${esc(error.message)}</p>`}
}
function bindEvidenceForm(body,id,dialog){const form=body.querySelector('#evidenceForm');if(!form)return;form.addEventListener('submit',async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form).entries()),editId=form.dataset.editId;try{await apiRequest(editId?`/api/evidence/${encodeURIComponent(editId)}`:`/api/cases/${encodeURIComponent(id)}/evidence`,{method:editId?'PUT':'POST',body:data});dialog.close();await openCaseDetail(id);document.querySelector('[data-case-tab="evidence"]')?.click();toast(editId?'Evidence details updated.':'Evidence recorded.')}catch(error){toast(error.message)}});const cancel=form.querySelector('[data-cancel-evidence]');if(cancel)cancel.onclick=()=>{form.replaceWith(document.createRange().createContextualFragment(evidenceEditorMarkup()));bindEvidenceForm(body,id,dialog)}}
function bindHearingForm(body,id,dialog){const form=body.querySelector('#hearingForm');if(!form)return;form.addEventListener('submit',async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form).entries()),editId=form.dataset.editId;try{await apiRequest(editId?`/api/hearings/${encodeURIComponent(editId)}`:`/api/cases/${encodeURIComponent(id)}/hearings`,{method:editId?'PUT':'POST',body:data});dialog.close();await openCaseDetail(id);document.querySelector('[data-case-tab=hearings]')?.click();toast(editId?'Hearing updated.':'Hearing scheduled.')}catch(error){toast(error.message)}});const cancel=form.querySelector('[data-cancel-hearing]');if(cancel)cancel.onclick=()=>{form.replaceWith(document.createRange().createContextualFragment(hearingEditorMarkup()));bindHearingForm(body,id,dialog)}}
async function navigate(next){page=next;await render();document.querySelector('#sidebar').classList.remove('open');window.scrollTo(0,0)}
function updateAccountUI(){const role=currentUser.role,name=currentUser.name,initial=initials(name);document.body.classList.toggle('can-manage',canManage());document.querySelector('#usersNav').hidden=role!=='Management Head';document.querySelector('#profileInitials').textContent=initial;document.querySelector('#topAvatar').textContent=initial;document.querySelector('#profileName').innerHTML=`${esc(name)}<small id="profileRole">${esc(role)}</small>`;document.querySelector('#menuName').textContent=name;document.querySelector('#menuRole').textContent=role;document.querySelector('#accountInitials').textContent=initial;document.querySelector('#accountName').textContent=name;document.querySelector('#accountRole').textContent=role;document.querySelector('#accountAccess').textContent=role}
async function authenticate(username,password){try{const result=await apiRequest('/api/auth/login',{method:'POST',body:{username,password}});if(!result?.user)throw new Error('Login response did not include an authenticated user.');currentUser=result.user;page='overview';return true}catch(error){return error.message}}
document.querySelector('#changePasswordForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,data=Object.fromEntries(new FormData(form).entries()),message=document.querySelector('#passwordChangeMessage');message.hidden=true;if(data.new_password!==data.confirm_password){message.textContent='The new passwords do not match.';message.hidden=false;return}delete data.confirm_password;try{const result=await apiRequest('/api/auth/change-password',{method:'POST',body:data});document.querySelector('#accountDialog').close();currentUser=null;const loginError=document.querySelector('#loginError');loginError.textContent=result.message;loginError.hidden=false;document.querySelector('#loginScreen').hidden=false;document.querySelector('#loginForm').reset();form.reset()}catch(error){message.textContent=error.message;message.hidden=false}});
document.addEventListener('submit',async event=>{if(event.target.id!=='createUserForm')return;event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form).entries());try{await apiRequest('/api/users',{method:'POST',body:data});form.reset();toast('User account created.');await render()}catch(error){toast(error.message)}});
document.addEventListener('click',async event=>{const roleButton=event.target.closest('[data-save-user-role]'),toggleButton=event.target.closest('[data-toggle-user]');if(roleButton){const id=roleButton.dataset.saveUserRole,role=document.querySelector(`[data-user-role=\"${id}\"]`).value;try{await apiRequest(`/api/users/${id}`,{method:'PUT',body:{role}});toast('User role updated.');await render()}catch(error){toast(error.message)}}else if(toggleButton){const id=toggleButton.dataset.toggleUser,active=toggleButton.dataset.active!=='1';try{await apiRequest(`/api/users/${id}`,{method:'PUT',body:{active}});toast(active?'User account enabled.':'User account disabled.');await render()}catch(error){toast(error.message)}}});
document.addEventListener('click',async event=>{const button=event.target.closest('[data-delete-user]');if(!button)return;const id=button.dataset.deleteUser,account=userAccounts.find(item=>String(item.id)===id);if(!account||!confirm(`Delete the account for ${account.name} (${account.username})? This cannot be undone.`))return;try{await apiRequest(`/api/users/${id}`,{method:'DELETE'});toast('User account deleted.');await render()}catch(error){toast(error.message)}});
document.querySelector('#loginForm').addEventListener('submit',async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget).entries()),form=event.currentTarget,button=form.querySelector('[type=submit]'),error=document.querySelector('#loginError');button.disabled=true;button.textContent='Signing in…';const result=await authenticate(data.username,data.password);button.disabled=false;button.innerHTML='Sign in <span>→</span>';if(result!==true){error.textContent=typeof result==='string'?result:'Incorrect username or password.';error.hidden=false;return}error.hidden=true;form.reset();document.querySelector('#loginScreen').hidden=true;await render({refreshData:false});void render({refreshData:true})});
document.querySelector('#signOutButton').onclick=async()=>{try{await apiRequest('/api/auth/logout',{method:'POST'})}catch(error){toast(error.message)}currentUser=null;closeProfileMenu();render();document.querySelector('[name="username"]').focus()};
async function deleteCase(id){if(!canManage())return;const record=records.find(c=>c.id===id);if(!record||!confirm(`Delete case ${id} — ${record.title}? This cannot be undone.`))return;try{await apiRequest(`/api/cases/${encodeURIComponent(id)}`,{method:'DELETE'});await render();toast('Case record deleted.')}catch(error){toast(error.message)}}
function entityKey(type,item){return type==='person'?item.id:(item.id||item.badge)}
async function deleteEntity(type,key){if(!canManage())return;const isPerson=type==='person',list=isPerson?persons:officers,item=list.find(x=>String(isPerson?x.id:(x.db_id||x.id))===String(key));if(!item||!confirm(`Delete ${isPerson?'person record':'team member'} “${item.name}”? This cannot be undone.`))return;try{await apiRequest(`/api/${isPerson?'persons':'officers'}/${encodeURIComponent(key)}`,{method:'DELETE'});await render();toast(isPerson?'Person record deleted.':'Team member removed.')}catch(error){toast(error.message)}}
function personLinkRow(link={}){const options=records.map(c=>`<option value="${esc(c.id)}" ${c.id===link.case_reference?'selected':''}>${esc(c.id)} · ${esc(c.title)}</option>`).join('');const roles=['suspect','witness','victim','person_of_interest'];return `<div class="person-link-row"><label>Case<select data-link-case><option value="">Choose a case</option>${options}</select></label><label>Role<select data-link-role>${roles.map(role=>`<option value="${role}" ${role===(link.role||'person_of_interest')?'selected':''}>${role.replaceAll('_',' ')}</option>`).join('')}</select></label><button type="button" class="btn secondary" data-remove-person-link aria-label="Remove linked case">Remove</button></div>`}
function openEntityDialog(type,item){if(!canManage())return;editingEntity={type,key:item?entityKey(type,item):null};const person=type==='person',title=item?`Edit ${person?'person record':'team member'}`:`Add ${person?'person of interest':'team member'}`,body=document.querySelector('#entityFormContent');const existing=item?.cases|| (item?.case?[{case_reference:item.case,role:'person_of_interest'}]:[]);const fields=person?`<label>Full name<input name="name" required></label><div class="wide person-links-editor"><div class="person-links-heading"><strong>Linked cases and roles</strong><button class="btn secondary" type="button" data-add-person-link>＋ Add case</button></div><div id="personCaseLinks">${(existing.length?existing:[{}]).map(personLinkRow).join('')}</div></div><label>Age<input name="age" type="number" min="0" max="120"></label><label>Status<select name="status"><option>Under investigation</option><option>In custody</option><option>Released on bail</option><option>Wanted</option><option>Unknown</option></select></label><label class="wide">Primary charge<input name="charge" required></label>`:`<label>Full name<input name="name" required></label><label>Role / designation<input name="role" required placeholder="e.g. Detective"></label><label>Badge ID<input name="badge" required></label>`;body.innerHTML=`<div class="dialog-top"><div><span class="eyebrow">${person?'PERSON RECORD':'TEAM MANAGEMENT'}</span><h2>${title}</h2></div><button class="close-btn" type="button" data-close-entity aria-label="Close">×</button></div><div class="form-grid">${fields}</div><div class="dialog-actions"><button class="btn secondary" type="button" data-close-entity>Cancel</button><button class="btn primary" type="submit">Save changes</button></div>`;document.querySelector('#entityDialog').showModal();document.querySelectorAll('[data-close-entity]').forEach(b=>b.onclick=()=>document.querySelector('#entityDialog').close());const form=document.querySelector('#entityForm');if(item)Object.entries(item).forEach(([k,v])=>{if(form.elements[k])form.elements[k].value=v});const links=document.querySelector('#personCaseLinks');const add=document.querySelector('[data-add-person-link]');if(add)add.onclick=()=>links.insertAdjacentHTML('beforeend',personLinkRow());if(links)links.onclick=e=>{const remove=e.target.closest('[data-remove-person-link]');if(remove){const rows=links.querySelectorAll('.person-link-row');if(rows.length>1)remove.closest('.person-link-row').remove();else remove.closest('.person-link-row').replaceWith(document.createRange().createContextualFragment(personLinkRow()))}}}
document.querySelector('#entityForm').addEventListener('submit',async event=>{event.preventDefault();if(!canManage()||!editingEntity)return;const {type,key}=editingEntity,d=Object.fromEntries(new FormData(event.currentTarget).entries()),isPerson=type==='person';if(isPerson)d.cases=[...document.querySelectorAll('#personCaseLinks .person-link-row')].map(row=>({case_reference:row.querySelector('[data-link-case]').value,role:row.querySelector('[data-link-role]').value})).filter(link=>link.case_reference);const submit=event.currentTarget.querySelector('[type=submit]');submit.disabled=true;try{await apiRequest(`/api/${isPerson?'persons':'officers'}${key===null?'':`/${encodeURIComponent(key)}`}`,{method:key===null?'POST':'PUT',body:d});document.querySelector('#entityDialog').close();editingEntity=null;await render();toast(key===null?'Record added.':'Record updated.')}catch(error){toast(error.message)}finally{submit.disabled=false}});
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function clearReferenceError(){const error=document.querySelector('#referenceError'),input=document.querySelector('#recordForm').elements.id;error.hidden=true;error.textContent='';input.removeAttribute('aria-invalid')}
function openDialog(record){if(!canManage())return;const dialog=document.querySelector('#recordDialog'),form=document.querySelector('#recordForm');form.reset();form.dataset.mode=record?'edit':'create';dialog.dataset.caseReference='';document.querySelector('#caseEntryFields').hidden=false;document.querySelector('#caseEntryActions').hidden=false;document.querySelector('#caseNextStep').hidden=true;const officerSelect=form.elements.officer;officerSelect.innerHTML='<option value="">Unassigned</option>'+officers.map(o=>`<option value="${esc(o.name)}">${esc(o.name)} — ${esc(o.role)} (${esc(o.badge)})</option>`).join('');clearReferenceError();document.querySelector('#dialogTitle').textContent=record?'Edit case record':'New case record';form.elements.id.readOnly=!!record;if(record){const category=form.elements.category;if(record.category&&![...category.options].some(option=>option.value===record.category))category.add(new Option(record.category,record.category));Object.entries(record).forEach(([k,v])=>{if(form.elements[k])form.elements[k].value=v})}dialog.showModal()}
function openEvidenceCasePicker(){if(!canManage())return;const select=document.querySelector('#evidenceCaseSelect');select.innerHTML=records.map(item=>`<option value="${esc(item.id)}">${esc(item.id)} · ${esc(item.title)}</option>`).join('');if(!records.length){toast('Create a case before recording evidence.');return}document.querySelector('#evidenceCaseDialog').showModal()}
async function continueCaseSetup(tab){const dialog=document.querySelector('#recordDialog'),id=dialog.dataset.caseReference;dialog.close();await render();await openCaseDetail(id);document.querySelector(`[data-case-tab="${tab}"]`)?.click()}
document.querySelectorAll('[data-close-dialog]').forEach(button=>button.addEventListener('click',()=>{clearReferenceError();document.querySelector('#recordDialog').close()}));
document.querySelectorAll('[data-close-evidence-case]').forEach(button=>button.addEventListener('click',()=>document.querySelector('#evidenceCaseDialog').close()));
document.querySelector('#evidenceCaseForm').addEventListener('submit',async event=>{event.preventDefault();const id=document.querySelector('#evidenceCaseSelect').value;document.querySelector('#evidenceCaseDialog').close();await openCaseDetail(id);document.querySelector('[data-case-tab="evidence"]')?.click()});
document.querySelector('#addEvidenceAfterCase').onclick=()=>continueCaseSetup('evidence');document.querySelector('#addHearingAfterCase').onclick=()=>continueCaseSetup('hearings');document.querySelector('#finishCaseSetup').onclick=async()=>{const id=document.querySelector('#recordDialog').dataset.caseReference;document.querySelector('#recordDialog').close();await render();toast(`Case ${id} saved.`)};
document.querySelectorAll('[data-close-case-detail]').forEach(button=>button.addEventListener('click',()=>document.querySelector('#caseDetailDialog').close()));
document.querySelector('#recordForm').elements.id.addEventListener('input',clearReferenceError);
document.querySelector('#recordForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form).entries()),editing=form.dataset.mode==='edit',id=data.id.trim(),error=document.querySelector('#referenceError'),button=document.querySelector('#saveRecord');data.id=id;button.disabled=true;button.textContent='Saving…';try{await apiRequest(editing?`/api/cases/${encodeURIComponent(id)}`:'/api/cases',{method:editing?'PUT':'POST',body:data});if(!editing){const dialog=document.querySelector('#recordDialog');dialog.dataset.caseReference=id;document.querySelector('#dialogTitle').textContent='Case saved';document.querySelector('#caseEntryFields').hidden=true;document.querySelector('#caseEntryActions').hidden=true;document.querySelector('#caseNextStep').hidden=false;await render();toast('Case saved. Add evidence or schedule a court hearing if needed, or select Finish.')}else{document.querySelector('#recordDialog').close();await render();toast('Case record updated.')}}catch(err){if(editing)toast(err.message);else{error.textContent=err.message;error.hidden=false;form.elements.id.setAttribute('aria-invalid','true')}}finally{button.disabled=false;button.innerHTML='Save record <span>→</span>'}});
function csvDownload(filename,rows){const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function exportCsv(){await downloadCsv('/api/reports/export?type=cases')}
async function downloadReport(index){const types=['summary','activity','workload','locations','resolution','cases','aging'];await downloadCsv(`/api/reports/export?type=${types[index]}`)}
function closeProfileMenu(){document.querySelector('#profileMenu').hidden=true;document.querySelector('#profileMenuToggle').setAttribute('aria-expanded','false')}
function openAccountDetails(){closeProfileMenu();document.querySelector('#accountDialog').showModal()}
document.querySelectorAll('[data-close-account]').forEach(button=>button.addEventListener('click',()=>document.querySelector('#accountDialog').close()));
function toggleProfileMenu(event){event.stopPropagation();const menu=document.querySelector('#profileMenu'),isOpen=!menu.hidden;menu.hidden=isOpen;document.querySelector('#profileMenuToggle').setAttribute('aria-expanded',String(!isOpen))}
document.querySelector('#profileMenuToggle').onclick=toggleProfileMenu;
document.querySelector('#accountDetailsButton').onclick=openAccountDetails;document.querySelector('#profileButton').onclick=toggleProfileMenu;
document.addEventListener('click',event=>{if(!document.querySelector('#profileArea').contains(event.target))closeProfileMenu()});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeProfileMenu()});
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.page)));document.querySelector('#mobileMenu').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');document.querySelector('.icon-btn').onclick=()=>navigate('activity');document.querySelector('#today').textContent=new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'});(async()=>{try{const session=await apiRequest('/api/auth/me');currentUser=session.user}catch{}await render()})();
